<?php
declare(strict_types=1);
namespace Tests\Feature;
use App\Models\{ClubInternalTransfer};use App\Services\Finance\ClubInternalTransferService;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use ReflectionClass;use Symfony\Component\Process\Process;use Tests\TestCase;use Throwable;
final class Milestone3iizxPostgresTransferConcurrencyTest extends TestCase
{
    public function test_concurrent_replays_tenant_identity_and_atomicity_hold_on_postgres():void
    {
        $this->assertSame('1',env('RUN_3IIZX_POSTGRES_CONCURRENCY'));$this->assertSame('pgsql',DB::connection()->getDriverName());$this->assertSame('lcb_3iizx_transfer_concurrency_test',DB::connection()->getDatabaseName());
        $exact=$this->fixture('PX');$key=(string)Str::uuid();$payload=$this->payload($exact,$key,100);$results=$this->race($exact,$payload,$payload);$this->assertSame(['success','success'],collect($results)->pluck('status')->sort()->values()->all());$this->assertSame($results[0]['transfer'],$results[1]['transfer']);$this->assertEffect($exact,1,1,2);
        $changed=$this->fixture('PC');$key=(string)Str::uuid();$results=$this->race($changed,$this->payload($changed,$key,101),$this->payload($changed,$key,202));$this->assertSame(['conflict','success'],collect($results)->pluck('status')->sort()->values()->all());$this->assertEffect($changed,1,1,2);
        $a=$this->fixture('PA');$b=$this->fixture('PB');$tenantKey=(string)Str::uuid();app(ClubInternalTransferService::class)->record($a['club'],$a['actor'],$this->payload($a,$tenantKey,303));app(ClubInternalTransferService::class)->record($b['club'],$b['actor'],$this->payload($b,$tenantKey,404));$this->assertSame(1,ClubInternalTransfer::where('club_id',$a['club']->id)->where('idempotency_key',$tenantKey)->count());$this->assertSame(1,ClubInternalTransfer::where('club_id',$b['club']->id)->where('idempotency_key',$tenantKey)->count());
        $atomic=$this->fixture('PF');DB::unprepared("CREATE FUNCTION reject_3iizx_transfer() RETURNS trigger LANGUAGE plpgsql AS \$\$ BEGIN IF NEW.source_type = 'club_internal_transfer' THEN RAISE EXCEPTION 'controlled transfer failure'; END IF; RETURN NEW; END \$\$");DB::unprepared('CREATE TRIGGER reject_3iizx_transfer BEFORE INSERT ON club_journal_entries FOR EACH ROW EXECUTE FUNCTION reject_3iizx_transfer()');try{app(ClubInternalTransferService::class)->record($atomic['club'],$atomic['actor'],$this->payload($atomic,(string)Str::uuid(),505));$this->fail('Controlled PostgreSQL journal failure must propagate.');}catch(Throwable){$this->assertSame(0,ClubInternalTransfer::where('club_id',$atomic['club']->id)->count());}$this->assertSame(0,DB::table('club_journal_entries')->where('club_id',$atomic['club']->id)->where('source_type',ClubInternalTransferService::SOURCE_TYPE)->count());DB::unprepared('DROP TRIGGER reject_3iizx_transfer ON club_journal_entries');DB::unprepared('DROP FUNCTION reject_3iizx_transfer()');
    }
    private function fixture(string $suffix):array{$reflection=new ReflectionClass(Milestone3iizxInternalCashBankTransferTest::class);$instance=$reflection->newInstanceWithoutConstructor();$method=$reflection->getMethod('fixture');return $method->invoke($instance,$suffix);}
    private function payload(array $f,string $key,int $amount):array{return ['accounting_date'=>'2027-08-10','source_account'=>$f['source']->public_id,'destination_account'=>$f['destination']->public_id,'fund'=>'GENERAL_CLUB_FUND','amount_paise'=>$amount,'description'=>'Concurrent transfer','external_reference'=>'PG','idempotency_key'=>$key];}
    private function race(array $f,array $first,array $second):array{$barrier=sys_get_temp_dir().DIRECTORY_SEPARATOR.'3iizx-transfer-'.Str::lower(Str::random(10));mkdir($barrier,0700,true);$processes=[];foreach([$first,$second] as $i=>$payload){$request=$barrier.DIRECTORY_SEPARATOR."request.{$i}.json";file_put_contents($request,json_encode(['club'=>$f['club']->id,'actor'=>$f['actor']->id,'payload'=>$payload],JSON_THROW_ON_ERROR));$processes[$i]=new Process([PHP_BINARY,base_path('tests/Support/Milestone3iizxTransferWorker.php'),$request,$barrier,(string)$i],base_path(),timeout:40);$processes[$i]->start();}$deadline=microtime(true)+20;while(!file_exists($barrier.DIRECTORY_SEPARATOR.'ready.0')||!file_exists($barrier.DIRECTORY_SEPARATOR.'ready.1')){if(microtime(true)>=$deadline)throw new \RuntimeException('Barrier timeout.');usleep(10000);}file_put_contents($barrier.DIRECTORY_SEPARATOR.'go','1');foreach($processes as $process){$process->wait();$this->assertTrue($process->isSuccessful(),$process->getErrorOutput().$process->getOutput());}return array_map(fn($i)=>json_decode((string)file_get_contents($barrier.DIRECTORY_SEPARATOR."result.{$i}.json"),true,flags:JSON_THROW_ON_ERROR),[0,1]);}
    private function assertEffect(array $f,int $transfers,int $journals,int $lines):void{$this->assertSame($transfers,ClubInternalTransfer::where('club_id',$f['club']->id)->count());$ids=DB::table('club_journal_entries')->where('club_id',$f['club']->id)->where('source_type',ClubInternalTransferService::SOURCE_TYPE)->pluck('id');$this->assertCount($journals,$ids);$this->assertSame($lines,DB::table('club_journal_lines')->whereIn('journal_entry_id',$ids)->count());}
}
